function markDirty(){if(APP.dirty)return;APP.dirty=true;const beat=selectedBeat(),cachedPath=beat?.render?.renderedVideoPath||beat?.renderedVideoPath||beat?.render?.previewPath;if(cachedPath){setPreviewState("stale","正在展示上一版成品预览 · 当前参数待重渲染");return}setPreviewState("stale","已修改，等待首次渲染")}async function saveBeat(internal=false){if(!internal&&!APP.dirty){syncButtonStates();return}if(!internal&&!beginAction("save"))return;setActionState("save-beat","loading","保存中...");try{readForm(true);await persist();APP.dirty=false;flashAction("save-beat","success","✓ 已保存");if(!internal)endAction();renderStudio()}catch(error){flashAction("save-beat","error","✕ 保存失败");if(!internal)endAction();toast(error.message||"保存失败");if(internal)throw error;}}
